Note: I corrected the library name to openpyxl (not "openpyx"). Below is a self-contained function that uses openpyxl for .xlsx and xlrd for .xls. It reads one sheet (by name or index) and writes it to a CSV file with the same base name if no destination is provided.

```python
import os
import csv
import datetime

def convert_excel_to_csv(excel_path, csv_path=None, sheet_name=None, sheet_index=0, encoding='utf-8', delimiter=','):
    """
    Convert an Excel file (.xlsx/.xlsm/.xls) to a CSV file.

    - Uses openpyxl for .xlsx/.xlsm/.xltx/.xltm files.
    - Uses xlrd for .xls files (install xlrd>=1.0.0; recent xlrd versions only support .xls).
    - By default writes to the same directory/filename but with .csv extension unless csv_path is provided.
    - By default reads the sheet specified by sheet_name (if provided) or the sheet_index (0-based).
    - Returns the path to the created CSV file.

    Raises informative ImportError if required libraries are missing.
    """
    if not os.path.isfile(excel_path):
        raise FileNotFoundError(f"Excel file not found: {excel_path}")

    base, ext = os.path.splitext(excel_path)
    ext = ext.lower()

    if csv_path is None:
        csv_path = base + '.csv'

    def _to_string(value):
        if value is None:
            return ''
        if isinstance(value, bool):
            return str(value)
        if isinstance(value, (datetime.datetime, datetime.date)):
            return value.isoformat()
        return str(value)

    # Handle modern Excel files with openpyxl
    if ext in ('.xlsx', '.xlsm', '.xltx', '.xltm'):
        try:
            from openpyxl import load_workbook
        except ImportError as e:
            raise ImportError("openpyxl is required to read .xlsx files. Install with: pip install openpyxl") from e

        wb = load_workbook(excel_path, read_only=True, data_only=True)
        if sheet_name:
            if sheet_name not in wb.sheetnames:
                raise ValueError(f"Sheet name '{sheet_name}' not found in workbook. Available sheets: {wb.sheetnames}")
            ws = wb[sheet_name]
        else:
            try:
                ws = wb.worksheets[sheet_index]
            except IndexError:
                raise IndexError(f"sheet_index {sheet_index} out of range. Workbook has {len(wb.worksheets)} sheets.")

        with open(csv_path, 'w', newline='', encoding=encoding) as f:
            writer = csv.writer(f, delimiter=delimiter)
            for row in ws.iter_rows(values_only=True):
                writer.writerow([_to_string(cell) for cell in row])

        return csv_path

    # Handle old .xls files with xlrd
    elif ext == '.xls':
        try:
            import xlrd
        except ImportError as e:
            raise ImportError("xlrd is required to read .xls files. Install with: pip install xlrd") from e

        book = xlrd.open_workbook(excel_path)
        if sheet_name:
            try:
                sheet = book.sheet_by_name(sheet_name)
            except xlrd.biffh.XLRDError:
                raise ValueError(f"Sheet name '{sheet_name}' not found in workbook. Available sheets: {book.sheet_names()}")
        else:
            try:
                sheet = book.sheet_by_index(sheet_index)
            except IndexError:
                raise IndexError(f"sheet_index {sheet_index} out of range. Workbook has {book.nsheets} sheets.")

        with open(csv_path, 'w', newline='', encoding=encoding) as f:
            writer = csv.writer(f, delimiter=delimiter)
            for r in range(sheet.nrows):
                row_out = []
                for c in range(sheet.ncols):
                    cell_type = sheet.cell_type(r, c)
                    cell_value = sheet.cell_value(r, c)
                    # If it's a date, convert using datemode
                    if cell_type == xlrd.XL_CELL_DATE:
                        try:
                            tup = xlrd.xldate_as_tuple(cell_value, book.datemode)
                            if tup[3:] == (0, 0, 0):
                                cell_value = f"{tup[0]:04d}-{tup[1]:02d}-{tup[2]:02d}"
                            else:
                                cell_value = f"{tup[0]:04d}-{tup[1]:02d}-{tup[2]:02d} {tup[3]:02d}:{tup[4]:02d}:{tup[5]:02d}"
                        except Exception:
                            cell_value = str(cell_value)
                    row_out.append(_to_string(cell_value))
                writer.writerow(row_out)

        return csv_path

    else:
        raise ValueError(f"Unsupported Excel extension: {ext}. Supported: .xlsx, .xlsm, .xltx, .xltm, .xls")
```

