Here's a self-contained Python function that converts a JSON string to an Excel (.xlsx) file using the openpyxl library (I replaced the mistaken "xllt" with the commonly used openpyxl). It handles empty JSON arrays by creating an Excel file with no data rows.

Note: install openpyxl if you don't have it already: pip install openpyxl

```python
import json
from openpyxl import Workbook

def json_to_excel(json_str: str, excel_path: str, sheet_name: str = "Sheet1") -> None:
    """
    Convert a JSON string to an Excel (.xlsx) file.

    - json_str: JSON string representing either a list (e.g. list of dicts), a single dict,
                a list of primitives, or other JSON types.
    - excel_path: path to write the .xlsx file (e.g. "output.xlsx").
    - sheet_name: optional sheet name to use.

    Behavior:
    - If json_str parses to an empty list [], the function creates an Excel file
      with the workbook and sheet but no data rows.
    - If the JSON is a list of dicts, headers are the union of keys in order of first appearance.
    - If the JSON is a single dict, headers are the dict's keys and a single data row is written.
    - If the JSON is a list of primitives, each value is written to its own row in one column.
    - If the JSON is a list of lists, each sublist becomes a row.
    - For mixed content, best-effort representation is used (dicts serialized when needed).
    """
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON: {exc}") from exc

    wb = Workbook()
    ws = wb.active
    ws.title = sheet_name

    if isinstance(data, dict):
        # Single object: write headers and one row
        headers = list(data.keys())
        if headers:
            ws.append(headers)
            ws.append([data.get(h) for h in headers])
    elif isinstance(data, list):
        if len(data) == 0:
            # Empty array: leave workbook with no data rows (sheet exists but no rows written)
            pass
        else:
            # List of dicts?
            if all(isinstance(item, dict) for item in data):
                # Collect headers in order of first appearance across items
                headers = []
                for item in data:
                    for k in item.keys():
                        if k not in headers:
                            headers.append(k)
                if headers:
                    ws.append(headers)
                    for item in data:
                        ws.append([item.get(h) for h in headers])
            # List of lists/tuples?
            elif all(isinstance(item, (list, tuple)) for item in data):
                for row in data:
                    ws.append(list(row))
            # List of primitives?
            elif all(not isinstance(item, (list, tuple, dict)) for item in data):
                for item in data:
                    ws.append([item])
            else:
                # Mixed types: best-effort output (serialize dicts to JSON strings)
                for item in data:
                    if isinstance(item, dict):
                        ws.append([json.dumps(item, ensure_ascii=False)])
                    elif isinstance(item, (list, tuple)):
                        ws.append(list(item))
                    else:
                        ws.append([item])
    else:
        # Primitive (number, string, bool, etc.): write single cell
        ws.append([data])

    wb.save(excel_path)
