def export_function_specs(f_list, file_path):
    """
    Export specifications of functions in `f_list` to a CSV at `file_path`.
    Uses pandas (corrected from user's 'pndas').

    CSV columns:
    - 'Function Name': function.__name__ (or repr if not available)
    - 'Number of Arguments': number of parameters in the function signature
    - 'Defaults': defaults for parameters (shown as "name=repr(value)" pairs, comma-separated)
    - 'Annotations': annotations for parameters and return (shown as "name: repr(annotation)" pairs, comma-separated)
    - 'Is Lambda': True if the function is a lambda (name == "<lambda>")

    Non-callable items in f_list are skipped.
    """
    import inspect
    import pandas as pd

    rows = []
    for f in f_list:
        if not callable(f):
            # skip non-callables
            continue

        name = getattr(f, "__name__", repr(f))

        # Try to get signature; some builtins may raise ValueError/TypeError
        try:
            sig = inspect.signature(f)
        except (ValueError, TypeError):
            sig = None

        if sig is not None:
            num_args = len(sig.parameters)

            # Defaults: collect parameters that have defaults
            defaults = {
                pname: p.default
                for pname, p in sig.parameters.items()
                if p.default is not inspect._empty
            }
            if defaults:
                defaults_str = ", ".join(f"{k}={repr(v)}" for k, v in defaults.items())
            else:
                defaults_str = ""

            # Annotations: use function.__annotations__ if present, else from signature
            ann = {}
            func_ann = getattr(f, "__annotations__", None)
            if func_ann:
                ann = func_ann
            else:
                # Fallback to signature annotations
                ann = {
                    pname: p.annotation
                    for pname, p in sig.parameters.items()
                    if p.annotation is not inspect._empty
                }
                if sig.return_annotation is not inspect._empty:
                    ann["return"] = sig.return_annotation

            if ann:
                annotations_str = ", ".join(f"{k}: {repr(v)}" for k, v in ann.items())
            else:
                annotations_str = ""
        else:
            # Could not obtain signature
            num_args = ""
            defaults_str = ""
            annotations_str = ""

        is_lambda = (name == "<lambda>")

        rows.append({
            "Function Name": name,
            "Number of Arguments": num_args,
            "Defaults": defaults_str,
            "Annotations": annotations_str,
            "Is Lambda": bool(is_lambda),
        })

    df = pd.DataFrame(rows, columns=[
        "Function Name", "Number of Arguments", "Defaults", "Annotations", "Is Lambda"
    ])
    df.to_csv(file_path, index=False)

Here's a self-contained Python function that uses the requests library (note the correct library name is "requests"), fetches GitHub user data, normalizes all string data to ASCII, and returns the normalized dictionary. It raises an HTTPError for non-2xx responses.

```python
import requests
import unicodedata
from typing import Any

def get_github_user_ascii(username: str, timeout: float = 10.0) -> dict:
    """
    Retrieve GitHub user information for `username`, normalize all string data to ASCII,
    and return the normalized data as a dictionary.

    Raises:
      requests.exceptions.RequestException (including HTTPError) on network/HTTP errors.

    Example:
      user = get_github_user_ascii("octocat")
    """
    if not username or not isinstance(username, str):
        raise ValueError("username must be a non-empty string")

    url = f"https://api.github.com/users/{username}"
    headers = {
        "Accept": "application/vnd.github.v3+json",
        "User-Agent": "python-requests/normalize-github-user"
    }

    resp = requests.get(url, headers=headers, timeout=timeout)
    # Raise for HTTP errors (404, 403, etc.)
    resp.raise_for_status()
    data = resp.json()

    def _normalize(obj: Any) -> Any:
        # Convert strings to ASCII-safe equivalents
        if isinstance(obj, str):
            return unicodedata.normalize("NFKD", obj).encode("ascii", "ignore").decode("ascii")
        # Recurse into mappings and sequences
        if isinstance(obj, dict):
            normalized = {}
            for k, v in obj.items():
                key = _normalize(k) if isinstance(k, str) else k
                normalized[key] = _normalize(v)
            return normalized
        if isinstance(obj, list):
            return [_normalize(item) for item in obj]
        if isinstance(obj, tuple):
            return tuple(_normalize(item) for item in obj)
        if isinstance(obj, set):
            return {_normalize(item) for item in obj}
        # Leave other types (int, float, bool, None, etc.) unchanged
        return obj

    return _normalize(data)
