```python
import numpy as np
from numbers import Number

def mean_and_variance(L):
    """
    Compute mean and variance of all numeric elements in a nested list/tuple/ndarray L.
    Returns a tuple (mean, variance) as Python floats.
    Raises ValueError if no numeric elements are found, TypeError for non-numeric elements.
    """
    def _flatten(x):
        if isinstance(x, (list, tuple, np.ndarray)):
            for item in x:
                yield from _flatten(item)
        else:
            yield x

    vals = []
    for item in _flatten(L):
        if isinstance(item, Number):
            vals.append(float(item))
        else:
            # try to convert things like numeric strings
            try:
                vals.append(float(item))
            except Exception:
                raise TypeError(f"Non-numeric element encountered: {item!r}")

    if not vals:
        raise ValueError("No numeric elements found in input.")

    arr = np.array(vals, dtype=float)
    return float(arr.mean()), float(arr.var())  # population variance (ddof=0)
