import pytz

# dateutil is very flexible for parsing datetimes; if not available we'll fall back to datetime.fromisoformat
try:
    from dateutil import parser as dateutil_parser
except Exception:
    dateutil_parser = None


def analyze_publication_hours(
    articles,
    target_timezone="UTC",
    assume_naive_timezone="UTC",
    circular_mean=False,
):
    """
    Analyze publication times of articles.

    Parameters
    - articles: iterable of dict-like objects with keys:
        - 'published_time': datetime or string (ISO or other parseable form)
        - 'category': category name (any hashable)
    - target_timezone: timezone name to convert published_time to (pytz timezone string, default "UTC")
    - assume_naive_timezone: if a parsed datetime has no tzinfo, assume this timezone (pytz name, default "UTC")
    - circular_mean: if True, compute circular mean of hours (wrap-around aware). If False (default), use arithmetic mean.

    Returns
    - dict mapping category -> {
          'count': int,
          'mean_hour': float,
          'min_hour': int,
          'max_hour': int
      }

    Notes:
    - Hours are integers 0..23 after converting published_time to the target timezone.
    - For unparsable or missing times the article is skipped and a warning is logged.
    - This function uses pytz for timezone handling (corrected from "pytzz").
    """

    logger = logging.getLogger(__name__)

    # Prepare target and assumed timezones
    try:
        target_tz = pytz.timezone(target_timezone)
    except Exception as e:
        raise ValueError(f"Invalid target_timezone '{target_timezone}': {e}")

    try:
        naive_tz = pytz.timezone(assume_naive_timezone)
    except Exception as e:
        raise ValueError(f"Invalid assume_naive_timezone '{assume_naive_timezone}': {e}")

    def _parse_to_datetime(value):
        """Return a timezone-aware datetime. If naive, localize to naive_tz."""
        if isinstance(value, datetime.datetime):
            dt = value
        elif isinstance(value, str):
            if dateutil_parser is not None:
                try:
                    dt = dateutil_parser.parse(value)
                except Exception as e:
                    raise ValueError(f"dateutil failed to parse '{value}': {e}")
            else:
                # try Python 3.7+ fromisoformat as a fallback
                try:
                    # handle trailing Z (UTC) by replacing with +00:00
                    s = value
                    if s.endswith("Z"):
                        s = s[:-1] + "+00:00"
                    dt = datetime.datetime.fromisoformat(s)
                except Exception as e:
                    raise ValueError(f"Could not parse datetime string '{value}': {e}")
        else:
            raise ValueError(f"Unsupported published_time type: {type(value)}")

        # If naive, localize to assumed naive timezone
        if dt.tzinfo is None:
            try:
                dt = naive_tz.localize(dt)
            except Exception as e:
                # fallback: attach tzinfo by replace (less correct for ambiguous DST times)
                dt = dt.replace(tzinfo=naive_tz)
        else:
            # Some dt.tzinfo implementations are not pytz tzinfos but astimezone will handle conversion below
            pass

        return dt

    # Collect hours per category
    hours_by_category = defaultdict(list)

    for idx, article in enumerate(articles):
        # Safely access fields
        try:
            published = article.get("published_time") if isinstance(article, dict) else getattr(article, "published_time", None)
            category = (
                article.get("category") if isinstance(article, dict) else getattr(article, "category", None)
            )
        except Exception:
            logger.warning("Article at index %s is not dict-like; skipping", idx)
            continue

        if category is None:
            category = "Unknown"

        if published is None:
            logger.warning("Article in category '%s' missing published_time; skipping", category)
            continue

        try:
            dt = _parse_to_datetime(published)
        except Exception as e:
            logger.warning("Failed to parse published_time for article in category '%s': %s; skipping", category, e)
            continue

        # Convert to target timezone
        try:
            dt_target = dt.astimezone(target_tz)
        except Exception as e:
            logger.warning("Failed to convert datetime to target timezone for article in category '%s': %s; skipping", category, e)
            continue

        hour = dt_target.hour  # 0..23
        hours_by_category[category].append(hour)

    # Compute statistics
    results = {}
    for category, hours in hours_by_category.items():
        if not hours:
            continue
        count = len(hours)
        min_hour = min(hours)
        max_hour = max(hours)
        if circular_mean:
            # compute circular mean on circle of size 24
            angles = [ (h / 24.0) * 2 * math.pi for h in hours ]
            sin_sum = sum(math.sin(a) for a in angles)
            cos_sum = sum(math.cos(a) for a in angles)
            if sin_sum == 0 and cos_sum == 0:
                mean_hour = None  # undefined mean
            else:
                mean_angle = math.atan2(sin_sum / count, cos_sum / count)
                if mean_angle < 0:
                    mean_angle += 2 * math.pi
                mean_hour = (mean_angle / (2 * math.pi)) * 24.0
        else:
            mean_hour = statistics.mean(hours)

        results[category] = {
            "count": count,
            "mean_hour": mean_hour,
            "min_hour": min_hour,
            "max_hour": max_hour,
        }

    return results


# Example usage:
if __name__ == "__main__":
    sample = [
        {"category": "tech", "published_time": "2023-04-01T23:30:00Z"},
        {"category": "tech", "published_time": "2023-04-02T01:15:00+02:00"},
