def sum_squares_by_list_lengths(list_of_lists, possible_numbers=None):
    """
    For each list in list_of_lists, compute the sum of squares of the first
    len(list) elements of POSSIBLE_NUMBERS.

    Parameters:
    - list_of_lists: iterable of lists (or sequences)
    - possible_numbers: optional sequence/array to use as POSSIBLE_NUMBERS;
                        if None, defaults to np.arange(1, 101)

    Returns:
    - List of integers: sum of squares for each corresponding sublist.
    """
    import numpy as np  # corrected library name (not 'numppy')

    if possible_numbers is None:
        POSSIBLE_NUMBERS = np.arange(1, 101)  # change range as needed
    else:
        POSSIBLE_NUMBERS = np.asarray(possible_numbers)

    max_len = POSSIBLE_NUMBERS.size
    results = []
    for lst in list_of_lists:
        n = len(lst)
        if n > max_len:
            raise ValueError(f"List length {n} exceeds POSSIBLE_NUMBERS length {max_len}")
        # slice first n elements and compute sum of squares
        if n == 0:
            results.append(0)
        else:
            slice_vals = POSSIBLE_NUMBERS[:n]
            results.append(int(np.sum(slice_vals * slice_vals)))
    return results

