    - pytesseract   : pip install pytesseract
    - optional chardet for better encoding detection: pip install chardet

    Example:
      text = extract_text_from_image("photo.jpg")
      data = extract_text_from_image("photo.jpg", out_encoding="utf-8")  # returns bytes
    """
    # Imports inside function to keep it self-contained
    from PIL import Image, ExifTags
    import pytesseract

    # Optional import for better encoding detection
    try:
        import chardet
    except Exception:
        chardet = None

    import unicodedata

    # Helper: decode bytes to Python str using chardet if available or sensible fallbacks
    def _bytes_to_str(b):
        if b is None:
            return ""
        if isinstance(b, str):
            return b
        if not isinstance(b, (bytes, bytearray)):
            # Try to cast to str
            try:
                return str(b)
            except Exception:
                return ""
        # b is bytes
        if chardet is not None:
            try:
                det = chardet.detect(b)
                enc = det.get("encoding") or "utf-8"
                return b.decode(enc, errors="replace")
            except Exception:
                pass
        # Fallback sequence
        for enc in ("utf-8", "utf-8-sig", "cp1252", "latin-1"):
            try:
                return b.decode(enc)
            except Exception:
                continue
        # Last resort
        return b.decode("utf-8", errors="replace")

    # Helper: normalize unicode
    def _normalize_text(s):
        if s is None:
            return ""
        if not isinstance(s, str):
            s = _bytes_to_str(s)
        return unicodedata.normalize("NFC", s).strip()

    # Optionally set custom tesseract command
    if tesseract_cmd:
        pytesseract.pytesseract.tesseract_cmd = tesseract_cmd

    # Try opening the image
    try:
        img = Image.open(image_path)
    except Exception as e:
        raise RuntimeError(f"Cannot open image {image_path!r}: {e}")

    # First attempt: OCR
    try:
        # Pass language if provided
        ocr_kwargs = {}
        if lang:
            ocr_kwargs["lang"] = lang
        ocr_text = pytesseract.image_to_string(img, **ocr_kwargs)
    except Exception as e:
        # If pytesseract fails, treat as empty and continue to fallback
        ocr_text = ""
        # You may want to log e in your application

    ocr_text = _normalize_text(ocr_text)

    # If OCR produced a non-empty result, use it
    if ocr_text:
        final_text = ocr_text
    else:
        # Fallback: try image comment / metadata
        final_text = ""
        # PIL stores JPEG comment in info['comment'] sometimes as bytes or list
        try:
            info = img.info or {}
            comment = info.get("comment") or info.get("Comment")
            if comment:
                # comment may be a list or bytes
                if isinstance(comment, (list, tuple)) and comment:
                    # take first element
                    comment = comment[0]
                final_text = _bytes_to_str(comment).strip()
        except Exception:
            final_text = ""

        if not final_text:
            # Try EXIF: UserComment or ImageDescription
            try:
                exif = img.getexif()
                if exif:
                    # map tag ids to names
                    tag_map = {v: k for k, v in ExifTags.TAGS.items()}
                    # common tags: "UserComment", "ImageDescription"
                    for tag_name in ("UserComment", "ImageDescription", "XPComment"):
                        tag_id = tag_map.get(tag_name)
                        if tag_id and tag_id in exif:
                            v = exif.get(tag_id)
                            if v:
                                # EXIF user comment sometimes stored as bytes with a charset prefix
                                # Try to decode robustly:
                                if isinstance(v, (bytes, bytearray)):
                                    decoded = _bytes_to_str(v)
                                else:
                                    decoded = str(v)
                                decoded = decoded.strip()
                                if decoded:
                                    final_text = decoded
                                    break
            except Exception:
                # ignore exif reading errors
                pass

    final_text = _normalize_text(final_text)

    # If out_encoding is specified, return bytes encoded in that encoding
    if out_encoding:
        try:
            return final_text.encode(out_encoding, errors="replace")
        except Exception as e:
            # If encoding fails, raise a clearer error
            raise RuntimeError(f"Failed to encode extracted text to {out_encoding}: {e}")

    # Default: return Python str (Unicode)
    return final_text
