```python
def geolocate_domains_in_text(text, timeout=5.0):
    """
    Extract URLs from `text`, obtain domains, and query ip-api.com for geolocation info.
    Returns a dict: { domain: { 'success': True, 'data': {...} } or { 'success': False, 'error': '...' } }

    Example:
        results = geolocate_domains_in_text("Check example.com and https://www.python.org/about")
    """
    import re
    import urllib.parse
    import requests

    # Regex to catch typical URLs, www-prefixed hosts, or bare domains with TLD
    pattern = r'https?://[^\s,;()<>"]+|www\.[^\s,;()<>"]+|[A-Za-z0-9.-]+\.[A-Za-z]{2,}(?:/[^\s,;()<>"]*)?'
    seen = set()
    domains = []

    for m in re.finditer(pattern, text):
        candidate = m.group(0).rstrip('.,;:)]}\'"')  # trim trailing punctuation
        if not candidate:
            continue

        # Ensure urlparse can find hostname by adding scheme if missing
        to_parse = candidate
        if not to_parse.startswith(('http://', 'https://')):
            to_parse = 'http://' + to_parse

        parsed = urllib.parse.urlparse(to_parse)
        hostname = parsed.hostname  # None if parsing failed
        if not hostname:
            continue

        # Normalize domain (lowercase, strip leading www.)
        hostname = hostname.lower()
        if hostname.startswith('www.'):
            hostname = hostname[4:]

        if hostname not in seen:
            seen.add(hostname)
            domains.append(hostname)

    results = {}
    if not domains:
        return results

    # Query ip-api for each domain
    base = "http://ip-api.com/json/"
    # Request fields: status,message,country,regionName,city,zip,lat,lon,isp,org,as,query
    fields = "status,message,country,regionName,city,zip,lat,lon,isp,org,as,query"

    for d in domains:
        try:
            resp = requests.get(f"{base}{d}", params={"fields": fields}, timeout=timeout)
            resp.raise_for_status()
            data = resp.json()
            if isinstance(data, dict) and data.get("status") == "success":
                # include the full returned JSON except "status" which is redundant
                results[d] = {"success": True, "data": data}
            else:
                # ip-api returns {"status":"fail","message":"..."} on error
                msg = data.get("message") if isinstance(data, dict) else "Unexpected response"
                results[d] = {"success": False, "error": msg}
        except requests.exceptions.RequestException as e:
            results[d] = {"success": False, "error": f"Request error: {e}"}
        except ValueError:
            results[d] = {"success": False, "error": "Invalid JSON response"}

    return results
```

Notes:
- This uses the free ip-api.com endpoint (no API key). Check ip-api usage limits and terms for production use.
