def download_url_from_json(json_str: str, key: str, save_dir: str | None = None) -> str:
    """
    Parse a JSON string to find a URL associated with `key`, download the file from that URL,
    and save it with a timestamped filename '{key}_{timestamp}.txt' where timestamp is
    formatted as '%Y%m%d%H%M%S%f' (microsecond precision).

    The file is saved in `save_dir` if provided, otherwise in the current working directory.
    Returns the full path to the saved file as a string.

    Raises ValueError on invalid JSON, missing key, non-URL value, or download failure.

    Example:
        json_str = '{"download_url": "https://example.com/data.txt"}'
        path = download_url_from_json(json_str, "download_url", "/tmp")
    """
    import json
    import datetime
    import pathlib
    import re
    import requests

    # Parse JSON
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON: {e}") from e

    # Recursively search for the first occurrence of the key
    def _find_key(obj, target):
        if isinstance(obj, dict):
            if target in obj:
                return obj[target]
            for v in obj.values():
                res = _find_key(v, target)
                if res is not None:
                    return res
        elif isinstance(obj, list):
            for item in obj:
                res = _find_key(item, target)
                if res is not None:
                    return res
        return None

    url = _find_key(data, key)
    if url is None:
        raise ValueError(f"Key '{key}' not found in JSON.")
    if not isinstance(url, str):
        raise ValueError(f"Value for key '{key}' is not a string URL: {url!r}")

    url = url.strip()
    if not url.lower().startswith(("http://", "https://")):
        raise ValueError(f"Value for key '{key}' does not look like an HTTP/HTTPS URL: {url!r}")

    # Prepare directory
    save_path = pathlib.Path(save_dir) if save_dir else pathlib.Path.cwd()
    try:
        save_path.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        raise ValueError(f"Could not create/save to directory '{save_path}': {e}") from e

    # Sanitize key for filename
    safe_key = re.sub(r"[^A-Za-z0-9._-]", "_", key)
    timestamp = datetime.datetime.now().strftime("%Y%m%d%H%M%S%f")
    filename = f"{safe_key}_{timestamp}.txt"
    full_path = save_path / filename

    # Download the file (streamed) and write to disk
    try:
        resp = requests.get(url, stream=True, timeout=30)
    except requests.RequestException as e:
        raise ValueError(f"Failed to initiate download from {url}: {e}") from e

    try:
        resp.raise_for_status()
        with open(full_path, "wb") as f:
            for chunk in resp.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
    except requests.RequestException as e:
        raise ValueError(f"HTTP error while downloading {url}: {e}") from e
    except OSError as e:
        raise ValueError(f"Failed to write to file '{full_path}': {e}") from e
    finally:
        resp.close()

    return str(full_path)
